// Relier la visite du Domaine et les séjours sans modifier les données existantes.
let estateMapMode='tout';
const estateLodgingPlaces=[['stay-cabane','cabane',41,-249],['stay-perchee','perchee',101,-249],['stay-container','container',161,-249],['stay-tiny','tiny',60,-195],['stay-lodge','lodge',144,-195]];
cityPlaces.find(p=>p.id==='habitats').stay='luxe';
cityPlaces.find(p=>p.id==='domaine').stay='luxe';
for(const [id,stay,x,y]of estateLodgingPlaces){const h=stayCatalog.find(p=>p.id===stay);cityPlaces.push({id,stay,x,y,name:h.name,short:h.type,label:h.type.toUpperCase(),icon:'⌂',desc:h.desc,stat:String(h.capacity),unit:'voyageurs maximum',stat2:money(h.night),unit2:'par nuit · fictif',detail:'Illustration conceptuelle d’un type d’habitat. Les disponibilités de séjour sont simulées dans ce navigateur.',action:'Voir les dates et réserver',route:'sejours'})}
const cityDetailBeforeEstate=cityDetailHTML;cityDetailHTML=function(){const place=cityPlaces.find(p=>p.id===citySelected);if(!place?.stay)return cityDetailBeforeEstate();const h=stayCatalog.find(p=>p.id===place.stay),q=stayQuote(h,staySearch),available=stayUnit(h,staySearch)!==null;return `<div class="eyebrow">EXPLORER · SÉJOURNER</div><div class="estate-place-art">${h.id==='luxe'?domainPlan():habitatArt(h.art)}</div><h2>${h.name}</h2><p>${h.desc}</p><div class="place-stat"><div><b>${h.capacity}</b>voyageurs max.</div><div><b>${money(h.night)}</b>/ nuit fictive</div></div><p class="estate-dates">${displayDate(staySearch.arrival)} → ${displayDate(staySearch.departure)}<br>${staySearch.guests} voyageur(s) · ${available?'Disponible en démo':'Indisponible pour ces critères'}</p><button class="btn" onclick="stayDetail('${h.id}')">Découvrir & réserver ↗</button><button class="textlink" style="display:block;margin-top:12px" onclick="location.hash='#sejours'">Choisir d’autres dates ↗</button><p class="citydetailinfo">Volumes conceptuels, prix et disponibilités fictifs. Les maisons en L du quartier et le hameau présentent différents scénarios d’habitat.</p>`};
function estateMapFilter(mode){estateMapMode=mode;if(mode==='sejours')citySelected='habitats';if(mode==='services')citySelected='casiers';render()}
const cityViewBeforeEstate=views.ville;views.ville=function(){let html=cityViewBeforeEstate();return `<div class="estate-map-intro"><div><div class="eyebrow">DE LA VISITE AU SÉJOUR</div><h2>Repérez votre prochain refuge.</h2><p>Les maisons en L, cabanes, containers, tiny house et lodge sont maintenant visibles dans le village. Sélectionnez un lieu pour ouvrir sa fiche.</p></div><a class="btn light" href="#sejours">Choisir mes dates ↗</a></div><div class="estate-map-filter" aria-label="Afficher les lieux du plan">${[['tout','Tout le Domaine'],['riverains','Maisons riveraines'],['sejours','À louer'],['services','Les services']].map(([key,label])=>`<button aria-pressed="${estateMapMode===key}" onclick="estateMapFilter('${key}')">${label}</button>`).join('')}</div>`+html};
const cityActionBeforeEstate=cityAction;cityAction=function(id){const p=cityPlaces.find(p=>p.id===id);if(p?.stay){stayDetail(p.stay);return}cityActionBeforeEstate(id)};
function locateStay(id){estateMapMode='sejours';citySelected=id==='luxe'?'domaine':'stay-'+id;$('#modal')?.close();if(location.hash==='#ville')render();else location.hash='#ville'}
const detailBeforeEstate=stayDetail;stayDetail=function(id){detailBeforeEstate(id);$('#modalbody').insertAdjacentHTML('beforeend',`<button class="btn light estate-map-link" onclick="locateStay('${id}')">⌖ Situer cet habitat sur le plan 3D</button>`)};
// Un changement de dates conserve la référence et libère l'ancien créneau seulement si le nouveau est disponible.
function stayUnitExcept(p,s,ignoreId){if(stayError(s)||s.guests>p.capacity)return null;for(let u=1;u<=p.units;u++)if(!state.staysV7.some(b=>b.id!==ignoreId&&b.habitat===p.id&&b.unit===u&&b.status!=='annule'&&overlaps(s.arrival,s.departure,b.arrival,b.departure)))return u;return null}
function editStayForm(id){const b=state.staysV7.find(b=>b.id===id);if(!b||b.status==='annule')return;const p=stayCatalog.find(p=>p.id===b.habitat);modal(`<div class="eyebrow">MODIFIER LE SÉJOUR FICTIF</div><h2 style="margin-top:18px">${p.name}</h2><p>Référence conservée : ${b.id}. Le nouveau total sera calculé avant votre confirmation.</p><form onsubmit="event.preventDefault();previewStayEdit('${id}',this)"><label for="edit-arrival">Arrivée</label><input type="date" name="arrival" id="edit-arrival" min="${nowDate()}" value="${b.arrival}" required><label for="edit-departure">Départ</label><input type="date" name="departure" id="edit-departure" min="${nowDate()}" value="${b.departure}" required><label for="edit-guests">Voyageurs</label><select name="guests" id="edit-guests">${Array.from({length:p.capacity},(_,i)=>`<option value="${i+1}" ${b.guests===i+1?'selected':''}>${i+1} personne(s)</option>`).join('')}</select><button class="btn" style="margin-top:20px">Vérifier les nouvelles dates</button></form>`)}
let pendingStayEdit=null;
function previewStayEdit(id,f){const b=state.staysV7.find(b=>b.id===id);if(!b||b.status==='annule')return;const p=stayCatalog.find(p=>p.id===b.habitat),s={arrival:f.arrival.value,departure:f.departure.value,guests:Number(f.guests.value)},err=stayError(s);if(err){toast(err);return}const unit=stayUnitExcept(p,s,id);if(!unit){toast('Le logement est indisponible pour ces nouvelles dates. Votre séjour initial est conservé.');return}const q=stayQuote(p,s);pendingStayEdit={id,...s};$('#modal').close();modal(`<div class="eyebrow">RÉCAPITULATIF DU CHANGEMENT</div><h2 style="margin-top:18px">Votre nouveau séjour.</h2><p>${p.name}<br>${displayDate(s.arrival)} → ${displayDate(s.departure)}<br>${s.guests} voyageur(s) · ${q.nights} nuit(s)</p><div class="quote-row"><span>Total précédent fictif</span><b>${money(b.total)}</b></div><div class="quote-row quote-total"><span>Nouveau total fictif</span><b>${money(q.total)}</b></div><p class="smallnote">Aucun paiement. Votre référence est conservée et le changement est enregistré dans l’historique local.</p><button class="btn" onclick="confirmStayEdit()">Confirmer la modification fictive</button>`)}
function confirmStayEdit(){if(!pendingStayEdit)return;const e=pendingStayEdit,b=state.staysV7.find(b=>b.id===e.id);if(!b||b.status==='annule')return;const p=stayCatalog.find(p=>p.id===b.habitat),unit=stayUnitExcept(p,e,b.id);if(!unit){toast('Les nouvelles dates sont devenues indisponibles. Votre séjour initial est conservé.');return}b.changes??=[];b.changes.push({date:nowDate(),arrival:b.arrival,departure:b.departure,guests:b.guests,total:b.total});Object.assign(b,{arrival:e.arrival,departure:e.departure,guests:e.guests,total:stayQuote(p,e).total,unit,updated:nowDate()});pendingStayEdit=null;save();$('#modal').close();render();toast('Dates modifiées. La référence de votre séjour est conservée.')}
function addBikeForStay(id){const b=state.staysV7.find(b=>b.id===id);if(b&&b.arrival>=nowDate())bikeSearch.date=b.arrival;location.hash='#velos'}
const reservationsBeforeEstate=reservationView;views.reservations=reservationView=function(){travelInit();let html=reservationsBeforeEstate();for(const b of state.staysV7){if(b.status==='annule')continue;html=html.replace(`<button class="btn light" onclick="cancelTravelForm('stay','${b.id}')">`,`<button class="btn light" onclick="editStayForm('${b.id}')">Modifier les dates</button><button class="btn light" onclick="cancelTravelForm('stay','${b.id}')">`);html=html.replace('<a class="textlink" href="#velos">Ajouter un vélo ↗</a>',`<button class="textlink" onclick="addBikeForStay('${b.id}')">Ajouter un vélo aux dates du séjour ↗</button>`)}return html.replace('Pour modifier des dates, annulez la réservation puis effectuez une nouvelle recherche. L’historique reste visible.','Vous pouvez modifier les dates d’un séjour, annuler une réservation et suivre les départs et retours des vélos. Les essais restent locaux.')};
// Navigation : le séjour au premier plan, la vie quotidienne dans un espace regroupé.
const renderBeforeEstate=render;render=function(){renderBeforeEstate();const current=location.hash.slice(1)||'accueil';const primary=['accueil','sejours','velos','reservations','ville','domaine'];const secondary=routes.filter(r=>!primary.includes(r[0]));const link=r=>`<a href="#${r[0]}" class="${r[0]===current?'active':''}" ${r[0]===current?'aria-current="page"':''}><span class="navicon">${r[1]}</span>${r[2]}</a>`;if(window.matchMedia('(max-width:850px)').matches){$('#nav').innerHTML=routes.map(link).join('');return}$('#nav').innerHTML=primary.map(id=>link(routes.find(r=>r[0]===id))).join('')+`<details class="estate-nav-group" ${secondary.some(r=>r[0]===current)?'open':''}><summary>La vie au Domaine</summary><div>${secondary.map(link).join('')}</div></details>`};
window.matchMedia('(max-width:850px)').addEventListener('change',()=>render());
render();
